import{_ as t,o as l,c as e,a3 as i}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"推薦本地模型","description":"按顯存推薦本地大模型（驗證通路、角色扮演、中文）；適用於 Ollama、LM Studio、KoboldCPP、llama.cpp 接 MiniTavern。","frontmatter":{"title":"推薦本地模型","description":"按顯存推薦本地大模型（驗證通路、角色扮演、中文）；適用於 Ollama、LM Studio、KoboldCPP、llama.cpp 接 MiniTavern。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"推薦本地模型 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"按顯存推薦本地大模型（驗證通路、角色扮演、中文）；適用於 Ollama、LM Studio、KoboldCPP、llama.cpp 接 MiniTavern。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/local/models"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/local/models"}]]},"headers":[],"relativePath":"zh-TW/local/models.md","filePath":"zh-TW/local/models.md","lastUpdated":1787224147000}'),o={name:"zh-TW/local/models.md"};function n(r,a,d,s,h,p){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="推薦模型" tabindex="-1">推薦模型 <a class="header-anchor" href="#推薦模型" aria-label="Permalink to &quot;推薦模型&quot;">​</a></h1><p>模型名與下載方式因工具而異；下表給出 <strong>體量與用途</strong> 建議。具體 pull / 文件名以各工具頁面為準。</p><h2 id="按硬件選體量" tabindex="-1">按硬件選體量 <a class="header-anchor" href="#按硬件選體量" aria-label="Permalink to &quot;按硬件選體量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>大致規模</th><th>內存/顯存粗略參考</th><th>適合</th></tr></thead><tbody><tr><td>1B–3B</td><td>約 4–8GB</td><td><strong>先驗證通路</strong>、低配機器</td></tr><tr><td>7B–9B</td><td>約 8–16GB</td><td>角色扮演常用甜點區</td></tr><tr><td>12B–14B</td><td>16GB+</td><td>質量更好，速度看顯卡</td></tr><tr><td>32B+</td><td>24GB+ 或大力量化</td><td>高配；手機連著也會等更久</td></tr></tbody></table><p>量化（Q4 / Q5 / IQ 等）越小越省資源、質量略降。GGUF 用戶優先選社區常用的 <code>Q4_K_M</code> / <code>Q5_K_M</code>。</p><h2 id="驗證通路-優先小模型" tabindex="-1">驗證通路（優先小模型） <a class="header-anchor" href="#驗證通路-優先小模型" aria-label="Permalink to &quot;驗證通路（優先小模型）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>場景</th><th>Ollama 示例</th><th>GGUF / 其它</th></tr></thead><tbody><tr><td>最快測通</td><td><code>llama3.2:3b</code>、<code>qwen2.5:3b</code></td><td>任意 3B 級 instruct GGUF</td></tr><tr><td>中文輕量</td><td><code>qwen2.5:3b</code> / <code>qwen2.5:7b</code></td><td>Qwen2.5 Instruct 量化</td></tr></tbody></table><p>先保證 <a href="/ultra_guides/zh-TW/connect-app/minitavern">測連成功</a>，再換大模型。</p><h2 id="角色扮演向提示" tabindex="-1">角色扮演向提示 <a class="header-anchor" href="#角色扮演向提示" aria-label="Permalink to &quot;角色扮演向提示&quot;">​</a></h2><ul><li>優先 <strong>Instruct / Chat</strong> 微調，而不是純基座補全模型。</li><li>社區常討論的 RP 向權重會隨時間變化；以你工具內能穩定加載、且上下文長度夠用為準。</li><li>上下文（context）太小會導致長設定/世界書截斷；7B 級可先從 4k–8k 試起，再按顯存加大。</li><li>在 MiniTavern 填寫的 <strong>模型名</strong> 必須與工具列表中的名稱 <strong>完全一致</strong>（含 tag，如 <code>:7b</code>）。</li></ul><h2 id="ollama-常用拉取示例" tabindex="-1">Ollama 常用拉取示例 <a class="header-anchor" href="#ollama-常用拉取示例" aria-label="Permalink to &quot;Ollama 常用拉取示例&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:14b</span></span></code></pre></div><p>更多命令見 <a href="/ultra_guides/zh-TW/ollama/models">Ollama · 下載與選擇模型</a>。</p><h2 id="lm-studio-koboldcpp-llama-cpp" tabindex="-1">LM Studio / KoboldCPP / llama.cpp <a class="header-anchor" href="#lm-studio-koboldcpp-llama-cpp" aria-label="Permalink to &quot;LM Studio / KoboldCPP / llama.cpp&quot;">​</a></h2><ol><li>在 <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> 等來源下載 <strong>GGUF</strong>（注意許可證與來源可信）。</li><li>在對應工具中加載同一文件。</li><li>打開 API / Server 後，把界面顯示的 <strong>model id</strong> 抄到 MiniTavern。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./tools">工具總覽</a> → 選定工具的「開服務」章節 → <a href="/ultra_guides/zh-TW/connect-app/minitavern">在 MiniTavern 中配置</a></p>`,17)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
